package workspace

// restore-workspace: clio's RestoreWorkspaceCommand as RestoreWorkspaceTool runs it, with WorkspaceOptions'
// defaults (NuGet restore, solution, build props on): the CreatioSDK version, the package download
// (PackageDownloader, then the Autogenerated folders), `dotnet restore` of CreatioSDK into .nuget, the
// .solution environment scripts, MainSolution.slnx and the build-props import in every package project.
//
// Not reproduced: clio answers a folder without .clio/workspaceSettings.json by creating a workspace in its own
// process working directory (CreateWorkspaceCommand resets the root to it), which writes files outside the
// requested path; this server reports the missing settings file instead.

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/Alexandr-Kravchuk/creatio-mcp-go/internal/creatio"
)

// RestoreRequest is RestoreWorkspaceArgs plus what the command reads from the resolved environment.
type RestoreRequest struct {
	Root string
}

const noPackagesEligible = "No packages are eligible for restore from .clio/workspaceSettings.json; package download was skipped."

// nugetRestoreProject is clio's tpl/NugetRestoreProj.csproj.tpl.
const nugetRestoreProject = "<Project Sdk=\"Microsoft.NET.Sdk\">\r\n  <PropertyGroup>\r\n    <TargetFramework>netstandard2.0</TargetFramework>\r\n" +
	"  </PropertyGroup>\r\n  <ItemGroup>\r\n    <PackageReference Include=\"$name$\" Version=\"$version$\" />\r\n  </ItemGroup>\r\n</Project>"

// RestoreWorkspace is RestoreWorkspaceCommand.Execute.
func RestoreWorkspace(ctx context.Context, client *creatio.Client, request RestoreRequest) creatio.CommandResult {
	log := &Log{}
	if err := restoreWorkspace(ctx, log, client, syncPaths{root: request.Root}); err != nil {
		log.Error(err.Error())
		return log.Result(1)
	}
	log.Info("Done")
	return log.Result(0)
}

func restoreWorkspace(ctx context.Context, log *Log, client *creatio.Client, paths syncPaths) error {
	settings, err := readSyncSettings(paths)
	if err != nil {
		return err
	}
	sdk, err := NewSDKVersions(ctx, log).Find(settings.ApplicationVersion)
	if err != nil {
		return err
	}
	packages := withoutExternal(filterPackages(log, settings.Packages, settings.IgnorePackages), settings.ExternalPackages)
	if len(packages) == 0 {
		log.Warning(noPackagesEligible)
	} else if err := downloadPackages(ctx, log, client, paths, packages); err != nil {
		return err
	}
	if err := restoreCreatioSDK(ctx, log, sdk, paths.nuget()); err != nil {
		return err
	}
	if err := createEnvironmentScripts(paths, sdk); err != nil {
		return err
	}
	if err := paths.layout().createWorkspaceSolution(log); err != nil {
		return err
	}
	return addBuildProps(log, paths)
}

// Find is CreatioSdkOnline.FindLatestSdkVersion: the newest published version with the application version's
// major, minor and build, else the newest; without an application version, the newest.
func (s *SDKVersions) Find(applicationVersion *string) (dotnetVersion, error) {
	if applicationVersion == nil {
		return s.Last()
	}
	wanted, err := parseDotnetVersion(*applicationVersion)
	if err != nil {
		return nil, err
	}
	versions := s.list()
	for _, version := range versions {
		if version.component(0) == wanted.component(0) && version.component(1) == wanted.component(1) &&
			version.component(2) == wanted.component(2) {
			return version, nil
		}
	}
	if len(versions) == 0 {
		return nil, errors.New(sdkVersionsUnavailable)
	}
	return versions[0], nil
}

// safePackageName is GetSafePackageName.
func safePackageName(name string) string {
	return strings.ReplaceAll(strings.ReplaceAll(name, " ", ""), ",", `","`)
}

// downloadPackages is PackageDownloader.DownloadPackages: nothing at all when the environment does not answer
// the ping, else every package archive downloaded, then unpacked over its folder, then the Autogenerated folders.
func downloadPackages(ctx context.Context, log *Log, client *creatio.Client, paths syncPaths, packages []string) error {
	if !client.PingApplication(ctx) {
		return nil
	}
	err := withTempDirectory(log, func(temp string) error {
		for _, name := range packages {
			safe := safePackageName(name)
			log.Line("Start download packages (" + safe + ").")
			if err := client.DownloadPackageArchive(ctx, name, combinePath(temp, safe+".zip")); err != nil {
				log.Line("Download packages (" + safe + ") not completed.")
				return err
			}
			log.Line("Download packages (" + safe + ") completed.")
		}
		for _, name := range packages {
			if err := unzipPackages(log, combinePath(temp, safePackageName(name)+".zip"), paths.packages()); err != nil {
				return err
			}
		}
		return nil
	})
	if err != nil {
		return err
	}
	return downloadAutogenerated(ctx, log, client, paths, packages)
}

// checkPackedPackage is PackageArchiver.CheckPackedPackageExistsAndNotEmpty.
func checkPackedPackage(path string) error {
	info, err := os.Stat(path)
	if err != nil || info.IsDir() {
		return fmt.Errorf("Package archive %s not found", path)
	}
	if info.Size() == 0 {
		return fmt.Errorf("Package archive %s is empty", path)
	}
	return nil
}

// unzipPackages is PackageArchiver.UnZipPackages(zip, overwrite, deleteGzFiles, unpackIsSameFolder): the
// archive's .gz packages extracted in a temporary folder, each unpacked over destination/<name>.
func unzipPackages(log *Log, archive, destination string) error {
	if err := checkPackedPackage(archive); err != nil {
		return err
	}
	return withTempDirectory(log, func(temp string) error {
		if err := unzip(archive, temp); err != nil {
			return err
		}
		files, _, err := directoryFiles(temp)
		if err != nil {
			return err
		}
		for _, file := range files {
			name := filepath.Base(file)
			extension := strings.ToLower(filepath.Ext(name))
			if extension != ".gz" || (!caseInsensitiveNames() && filepath.Ext(name) != ".gz") {
				continue
			}
			packageName := strings.TrimSuffix(name, filepath.Ext(name))
			log.Line("Start unzip package (" + packageName + ").")
			if err := checkPackedPackage(file); err != nil {
				return err
			}
			target := combinePath(destination, packageName)
			if err := createOrClearDirectory(target); err != nil {
				return err
			}
			if err := unpackGzip(file, target); err != nil {
				return err
			}
			log.Line("Unzip package (" + packageName + ") completed.")
		}
		return nil
	})
}

// downloadAutogenerated is ApplicationDownloader.DownloadAutogeneratedPackages: each package's Autogenerated
// folder replaced by the environment's, then the files of its own C# schemas removed from it. clio downloads in
// parallel and reports failures as an AggregateException; this server downloads in order.
func downloadAutogenerated(ctx context.Context, log *Log, client *creatio.Client, paths syncPaths, packages []string) error {
	err := withTempDirectory(log, func(temp string) error {
		for _, name := range packages {
			archiveName := "Autogenerated." + name
			log.Line("Run download " + archiveName)
			archive := combinePath(temp, archiveName+".gz")
			if err := client.DownloadAutogeneratedFolder(ctx, name, archive); err != nil {
				return err
			}
			target := combinePath(paths.pkg(name), "Autogenerated")
			if err := createOrClearDirectory(target); err != nil {
				return err
			}
			if err := unpackGzip(archive, target); err != nil {
				return err
			}
			if err := os.Remove(archive); err != nil {
				return err
			}
		}
		return nil
	})
	if err != nil {
		return fmt.Errorf("One or more errors occurred. (%s)", err.Error())
	}
	for _, name := range packages {
		schemas := combinePath(paths.pkg(name), "Schemas")
		if !directoryExists(schemas) {
			continue
		}
		files, err := allFiles(schemas, -1, false)
		if err != nil {
			return err
		}
		for _, file := range files {
			if !matchesExtension(file, ".cs") {
				continue
			}
			base := filepath.Base(file)
			generated := combinePath(combinePath(combinePath(paths.pkg(name), "Autogenerated"), "Src"),
				strings.TrimSuffix(base, filepath.Ext(base))+"."+name+".cs")
			if fileExists(generated) {
				if err := os.Remove(generated); err != nil {
					return err
				}
			}
		}
	}
	return nil
}

// matchesExtension is a "*<extension>" search pattern, without case where the platform matches names so.
func matchesExtension(path, extension string) bool {
	if caseInsensitiveNames() {
		return strings.HasSuffix(strings.ToLower(path), strings.ToLower(extension))
	}
	return strings.HasSuffix(path, extension)
}

// runDotnet runs the dotnet CLI as ProcessExecutor.Execute does (stdin closed, the server's working directory)
// and answers stdout and stderr each without trailing line breaks, joined by a newline; a program that does not
// start answers .NET's start failure text. Tests replace it.
var runDotnet = func(ctx context.Context, args ...string) string {
	command := exec.CommandContext(ctx, "dotnet", args...)
	var stdout, stderr bytes.Buffer
	command.Stdout, command.Stderr, command.Stdin = &stdout, &stderr, bytes.NewReader(nil)
	if err := command.Run(); err != nil {
		var exitErr *exec.ExitError
		if !errors.As(err, &exitErr) {
			directory, _ := os.Getwd()
			return fmt.Sprintf("An error occurred trying to start process 'dotnet' with working directory '%s'. %s",
				directory, startFailureText(err))
		}
	}
	out := strings.TrimRight(stdout.String(), "\r\n")
	errText := strings.TrimRight(stderr.String(), "\r\n")
	switch {
	case out == "":
		return errText
	case errText == "":
		return out
	}
	return out + newLine() + errText
}

func startFailureText(err error) string {
	if errors.Is(err, exec.ErrNotFound) || errors.Is(err, os.ErrNotExist) {
		return "No such file or directory"
	}
	return err.Error()
}

// restoreCreatioSDK is NugetPackageRestorer.RestoreToNugetFileStorage for CreatioSDK: `dotnet restore` of a
// throw-away project that references the version, into .nuget; dotnet's output is logged with the project's
// path replaced by the quoted destination.
func restoreCreatioSDK(ctx context.Context, log *Log, version dotnetVersion, destination string) error {
	var output string
	err := withQuietTempDirectory(log, func(temp string) error {
		project := filepath.Join(temp, "NugetRestoreProj.csproj")
		content := strings.ReplaceAll(strings.ReplaceAll(nugetRestoreProject, "$name$", "CreatioSDK"), "$version$", version.String())
		if err := writeAllText(project, content); err != nil {
			return err
		}
		output = runDotnet(ctx, "restore", project, "--source", "https://api.nuget.org/v3/index.json",
			"--packages", destination, "--force", "--no-cache")
		output = strings.ReplaceAll(output, project, `"`+destination+`"`)
		return nil
	})
	if err != nil {
		return err
	}
	log.Line(output)
	return nil
}

// createEnvironmentScripts is EnvironmentScriptCreator.Create: .solution/set-framework-environment.cmd and
// set-netcore-environment.cmd pointing at the restored SDK, relative to a package project folder.
func createEnvironmentScripts(paths syncPaths, version dotnetVersion) error {
	text, err := template("set-environment.cmd")
	if err != nil {
		return err
	}
	projectFolder := combinePath(combinePath(paths.packages(), "PackageName"), "Files")
	for _, script := range []struct{ file, library, framework string }{
		{"set-framework-environment.cmd", "net40", "net472"},
		{"set-netcore-environment.cmd", "netstandard2.0", "netstandard2.0"},
	} {
		sdkPath := combineAll(paths.nuget(), "creatiosdk", version.String(), "lib", script.library)
		content := strings.ReplaceAll(strings.ReplaceAll(text, "$CoreLibPath$", relativePath(projectFolder, sdkPath)),
			"$CoreTargetFramework$", script.framework)
		if err := writeAllText(combinePath(paths.solution(), script.file), content); err != nil {
			return err
		}
	}
	return nil
}

const (
	buildPropsImportProject   = `..\..\..\.build-props\env.$(Configuration).props`
	buildPropsImportCondition = `Exists('..\..\..\.build-props\env.$(Configuration).props')`
)

// addBuildProps is WorkspaceRestorer's AddBuildProps step: .build-props created from the template when the
// workspace has none, then the import added to every *.csproj up to two folders below packages.
func addBuildProps(log *Log, paths syncPaths) error {
	if !directoryExists(paths.packages()) {
		return fmt.Errorf("Could not find a part of the path '%s'.", fullPath(paths.packages()))
	}
	listed, err := allFiles(paths.packages(), 2, true)
	if err != nil {
		return err
	}
	if err := createBuildProps(paths); err != nil {
		return err
	}
	for _, file := range listed {
		if !matchesExtension(file, ".csproj") {
			continue
		}
		if err := appendBuildPropsImport(log, file); err != nil {
			return err
		}
	}
	return nil
}

func createBuildProps(paths syncPaths) error {
	if directoryExists(paths.buildProps()) {
		return nil
	}
	files, err := templatesUnder("workspace/.build-props")
	if err != nil {
		return err
	}
	if err := os.MkdirAll(paths.buildProps(), 0o777); err != nil {
		return err
	}
	for _, file := range files {
		if err := copyTemplateFile(file, filepath.Join(paths.buildProps(), filepath.Base(file.path))); err != nil {
			return err
		}
	}
	return nil
}

// appendBuildPropsImport is WorkspaceRestorer.AppendProps.
func appendBuildPropsImport(log *Log, path string) error {
	text, err := readAllText(path)
	if err != nil {
		return err
	}
	if strings.TrimSpace(text) == "" {
		log.Warning("[WARNING] Project file " + path + " is empty or contains only whitespace.")
		return nil
	}
	document, err := parseXML(text)
	if err != nil {
		return err
	}
	project := document.root()
	if project == nil || project.name != "Project" {
		project = nil
	} else if namespace, ok := project.attribute("xmlns"); ok && namespace != "" {
		project = nil
	}
	if project == nil {
		log.Warning("[WARNING] Project file " + path + " does not contain a root <Project> node.")
		return nil
	}
	for _, child := range project.children {
		if child.kind != xmlElement || child.name != "Import" {
			continue
		}
		importProject, _ := child.attribute("Project")
		condition, _ := child.attribute("Condition")
		if importProject == buildPropsImportProject && condition == buildPropsImportCondition {
			return nil
		}
	}
	element := &xmlNode{kind: xmlElement, name: "Import"}
	element.setAttribute("Project", buildPropsImportProject)
	element.setAttribute("Condition", buildPropsImportCondition)
	project.children = append([]*xmlNode{element}, project.children...)
	saved, bom := document.save()
	if bom {
		saved = "\uFEFF" + saved
	}
	return writeAllText(path, saved)
}
